// Cleanup for text generated by the small local chat model. It can fall into repetition loops
// ("もうもうもうもう…"), echo another speaker's line, or prefix its own name; none of that should
// reach the chat or be fed back into the next prompt, where it snowballs.

const SPEAKER_PREFIX = /^\s*[[［【][^\]］】\n]{1,30}[\]］】]\s*[:：]\s*/;
/** A unit of 1-40 characters repeated 4+ times in a row ("もうもうもうもう、もうもうもうもう、…"). */
const REPEATED_UNIT = /(.{1,40}?)\1{3,}/gsu;
const SENTENCE_END = /(?<=[。！？!?…\n])/u;
const FAILURE_PATTERN = /^（.{1,40}?(は考え中\.\.\.|の返信を作れませんでした[:：][\s\S]*)）$/u;

/** True for the placeholder text the server returns when a reply could not be generated. */
export function isFailedReplyText(text: string): boolean {
  return FAILURE_PATTERN.test(text.trim());
}

function trimToSentence(text: string, maxChars: number): string {
  if (text.length <= maxChars) return text;
  const cut = text.slice(0, maxChars);
  const end = Math.max(
    cut.lastIndexOf("。"),
    cut.lastIndexOf("！"),
    cut.lastIndexOf("？"),
    cut.lastIndexOf("!"),
    cut.lastIndexOf("?"),
  );
  return end >= maxChars * 0.4 ? cut.slice(0, end + 1) : `${cut.trimEnd()}…`;
}

/**
 * Removes speaker prefixes, collapses repetition loops, drops repeated sentences and bounds the
 * length. Leaves normal text untouched.
 */
export function cleanGeneratedText(raw: string, maxChars = 360): string {
  let text = raw
    .replace(/<\/?think>/g, "")
    .replace(SPEAKER_PREFIX, "")
    .trim();
  text = text.replace(REPEATED_UNIT, "$1");
  const seen = new Set<string>();
  const sentences: string[] = [];
  for (const sentence of text.split(SENTENCE_END)) {
    const key = sentence.replace(/\s+/g, "");
    if (!key || seen.has(key)) continue;
    seen.add(key);
    sentences.push(sentence);
  }
  return trimToSentence(sentences.join("").trim(), maxChars);
}

function normalize(text: string): string {
  return text.replace(/[\s、。！？!?…「」『』（）()～〜♪❤️✨💕😅]/gu, "");
}

/** True when `reply` mostly repeats something already said (a verbatim echo of another speaker). */
export function echoesEarlierLine(reply: string, earlier: string[]): boolean {
  const probe = normalize(reply).slice(0, 24);
  if (probe.length < 12) return false;
  return earlier.some((line) => normalize(line).includes(probe));
}
